72	func getLeaderID(
73		view uint64,
74		n uint64,
75		nodes []uint64,
76		leaderRotation bool,
77		decisionsInView uint64,
78		decisionsPerLeader uint64,
79		blacklist []uint64,
80	) uint64 {
81		blackListed := make(map[uint64]struct{})
82		for _, i := range blacklist {
83			blackListed[i] = struct{}{}
84		}
85	
86		if !leaderRotation {
87			return nodes[view%n]
88		}
89	
90		for i := range len(nodes) {
91			index := (view + (decisionsInView / decisionsPerLeader)) + uint64(i)
92			node := nodes[index%n]
93			_, exists := blackListed[node]
94			if !exists {
95				return node
96			}
97		}
98	
99		panic(fmt.Sprintf("all %d nodes are blacklisted", len(nodes)))
100	}
