113	func (vs *voteSet) clear(n uint64) {
114		// Drain the votes channel
115		for len(vs.votes) > 0 {
116			<-vs.votes
117		}
118	
119		vs.voted = make(map[uint64]struct{}, n)
120		vs.votes = make(chan *vote, n)
121	}
