194	// InFlightProposal returns an in-flight proposal or nil if there is no such.
195	func (ifp *InFlightData) InFlightProposal() *types.Proposal {
196		ifp.lock.RLock()
197		defer ifp.lock.RUnlock()
198	
199		if ifp.v == nil {
200			return nil
201		}
202	
203		return ifp.v.proposal
204	}
