337	// MsgToString converts a given message to a printable string
338	func MsgToString(m *protos.Message) string {
339		if m == nil {
340			return "empty message"
341		}
342		switch m.GetContent().(type) {
343		case *protos.Message_PrePrepare:
344			return prePrepareToString(m.GetPrePrepare())
345		case *protos.Message_NewView:
346			return newViewToString(m.GetNewView())
347		case *protos.Message_ViewData:
348			return signedViewDataToString(m.GetViewData())
349		case *protos.Message_HeartBeat:
350			return heartBeatToString(m.GetHeartBeat())
351		case *protos.Message_HeartBeatResponse:
352			return heartBeatResponseToString(m.GetHeartBeatResponse())
353		default:
354			return m.String()
355		}
356	}
